from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # Was pinned to [33, 33, 33] (sums to 99) after 49f71f0 dropped the
    # remainder pass; SET-2214 restores exact totals. Extra cents go to the
    # earliest parts.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_weighted_exact_parts():
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]
    assert allocate(57, [1, 3]) == [14, 43]


def test_parts_stay_within_one_cent_of_floor():
    total, weights = 12345, [3, 5, 7, 11]
    denom = sum(weights)
    parts = allocate(total, weights)
    assert sum(parts) == total
    for part, w in zip(parts, weights):
        assert 0 <= part - total * w // denom <= 1


def test_negative_total_sums_exactly():
    assert sum(allocate(-100, [1, 1, 1])) == -100


def test_zero_weight_gets_nothing():
    assert allocate(5, [0, 1, 1]) == [0, 3, 2]


def test_rejects_bad_weights():
    import pytest

    for weights in ([], [0, 0], [1, -1]):
        with pytest.raises(ValueError):
            allocate(10, weights)

