from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # Remainder goes one unit each to the first parts (pre-51c0183 behaviour).
    # The old pin of [33, 33, 33] summed to 99 and was the SET-2214 regression.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_equal_split_remainder_two():
    assert allocate(101, [1, 1, 1]) == [34, 34, 33]


def test_largest_remainder_wins_leftover():
    # exact shares: 16.67, 16.67, 66.67 -> two leftover units go to the
    # two largest remainders, ties broken by earliest position.
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]
    assert allocate(57, [1, 3]) == [14, 43]


def test_zero_weight_gets_nothing():
    assert allocate(100, [0, 1, 1]) == [0, 50, 50]


def test_zero_and_negative_totals_still_sum():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]
    parts = allocate(-100, [1, 1, 1])
    assert sum(parts) == -100


