    parts = allocate(total, weights)
    assert sum(parts) == total
    for w, p in zip(weights, parts):
        assert abs(total * w / sum(weights) - p) < 1


def test_zero_weight_gets_nothing():
    assert allocate(5, [0, 1, 1]) == [0, 3, 2]


def test_negative_total_mirrors_positive():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]
    assert allocate(-57, [1, 3]) == [-p for p in allocate(57, [1, 3])]


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


@pytest.mark.parametrize("weights", [[], [0, 0], [1, -1, 2]])
def test_rejects_bad_weights(weights):
    with pytest.raises(ValueError):
        allocate(100, weights)
