    "total, weights",
    [
        (1, [1, 1, 1]),
        (2, [1, 1, 1]),
        (99, [7, 11, 13, 17]),
        (123456, [3, 0, 5, 9, 1]),
        (-999, [2, 3, 7]),
    ],
)
def test_parts_sum_to_total_and_stay_within_one_cent(total, weights):
    parts = allocate(total, weights)
    assert sum(parts) == total
    denom = sum(weights)
    for part, w in zip(parts, weights):
        assert abs(part - total * w / denom) < 1


